package br.gov.dere.application.certificate;
import br.gov.dere.integration.certificate.PocSecretBox; import br.gov.dere.persistence.*; import java.io.*; import java.security.*; import java.time.*; import java.util.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.web.multipart.MultipartFile;
@Service public class CertificateService { private final DereEntityCertificateRepository repo; private final PocSecretBox box; public CertificateService(DereEntityCertificateRepository r,@Value("${dere.certificate.encryption-key:local-poc-change-me}") String key){repo=r;box=new PocSecretBox(key);} public DereEntityCertificateEntity save(Long entityId,String label,MultipartFile file,String password)throws Exception{if(file.isEmpty())throw new IllegalArgumentException("Arquivo vazio");var ks=KeyStore.getInstance("PKCS12");try(var in=file.getInputStream()){ks.load(in,password.toCharArray());}String alias=ks.aliases().nextElement();var cert=(java.security.cert.X509Certificate)ks.getCertificate(alias);var entity=new DereEntityCertificateEntity(entityId,label,box.encrypt(file.getBytes()),box.encrypt(password),alias,cert.getNotAfter().toInstant());return repo.save(entity);} public KeyStore load(Long id)throws Exception{return loadForSigning(id).keyStore();} public LoadedCertificate loadForSigning(Long id)throws Exception{var e=repo.findById(id).orElseThrow();var password=box.decrypt(e.getPasswordCiphertext()).toCharArray();var ks=KeyStore.getInstance("PKCS12");ks.load(new ByteArrayInputStream(box.decrypt(e.getP12Ciphertext())),password);return new LoadedCertificate(ks,password,e.getAliasName());} public List<CertificateDto> list(Long entityId){return repo.findByEntityIdAndActiveTrue(entityId).stream().map(e->new CertificateDto(e.getId(),e.getLabel(),e.getAliasName(),e.getValidUntil())).toList();} public record CertificateDto(Long id,String label,String alias,Instant validUntil){} public record LoadedCertificate(KeyStore keyStore,char[] password,String alias){} }
